      brief: `**財務管理的第一原則：今天的一塊錢比明天的一塊錢值錢。**

**三個理由**（缺一不可，考題常問）：
1. **投資機會**——今天拿到就能投入生利，這是**最根本的理由**
2. **通貨膨脹**——未來的一塊錢購買力較低
3. **不確定性**——未來的錢可能收不到

**★ 兩個核心公式**：

**終值**（今天的錢 → 未來值多少）：
\`FV = PV × (1+r)ⁿ\`

**現值**（未來的錢 → 今天值多少）：
\`PV = FV / (1+r)ⁿ\`

**兩者互為倒數關係**——複利是往前推，折現是往後拉。

**\`(1+r)ⁿ\` 稱為複利因子**，\`1 / (1+r)ⁿ\` 稱為**折現因子**。

**★ 折現率 r 的三個名字**，指的是同一件事：
- **機會成本**——把錢投在這裡就放棄了別處的報酬
- **必要報酬率**——承擔這個風險，投資人要求的最低報酬
- **資金成本**——公司取得這筆錢要付的代價

**風險越高 → r 越高 → 現值越低。** 這一句貫穿整個財管。

**複利與單利的差距隨時間急遽擴大**：10% 之下，單利 10 年變 2 倍，複利變 2.59 倍；30 年則是 4 倍 vs **17.45 倍**。`,
      advanced: `**折現的本質是「換算到同一個時點才能比較」**。財務決策幾乎都在比較發生在不同時點的現金流，而**不同時點的金額不能直接相加減**——這是財管與會計最根本的差別之一。**把所有現金流折到同一時點（通常是今天）之後，加減才有意義。**

**★ 72 法則**（心算利器，面試很好用）：
**本金翻倍所需年數 ≈ 72 / 利率（百分比）**
- 8% → 約 9 年翻倍
- 6% → 約 12 年
- 12% → 約 6 年

它是 \`ln2 / ln(1+r)\` 的近似，**在 6%–10% 的區間相當準確**。**能當場心算「這個報酬率幾年翻倍」，比按計算機更有說服力。**

**★ 名目利率 vs 實質利率**：
**Fisher 方程式**精確式為 \`(1 + 名目) = (1 + 實質) × (1 + 通膨)\`，
常用近似為 \`實質 ≈ 名目 − 通膨\`。**通膨很高時近似會失準**，須用精確式。

**關鍵原則：現金流與折現率必須「口徑一致」**——**名目現金流用名目利率折現、實質現金流用實質利率折現**。混用是資本預算最常見的錯誤之一，會系統性高估或低估 NPV（見 [[fin-06-03]]）。

**折現率的微小差異會造成巨大影響**，這一點在評價長期資產時特別關鍵：10 年後的 100 萬，在 r = 5% 時現值約 61.4 萬，r = 10% 時降至約 38.6 萬——**折現率翻倍，現值少了近四成**。**期間越長，對折現率越敏感**，這解釋了為什麼成長股（現金流集中在遙遠未來）的股價對利率變動反應最劇烈。

**複利的兩個常見誤解**：
1. **「平均報酬率」不是「實際累積報酬率」**——報酬率跨期是連乘，必須用幾何平均（連回統計學的 [[stat-01-02]]）。第一年 +50%、第二年 −50%，算術平均為 0，實際卻虧損 25%
2. **複利對「時間」的敏感度高於對「報酬率」的敏感度**——早開始十年的效果，往往大於報酬率高兩個百分點

**現金流量時間軸是解題的必備工具**：把每一期的現金流畫在時間軸上，標清楚**期初（t=0）與期末**。**財管計算題最常見的失分不是公式錯，而是期數數錯**——特別是「第一期現金流發生在期初還是期末」。`,
      example: `**退休儲蓄的複利威力**是最直觀的例子。假設年報酬率 7%：

- **25 歲開始**，每年投入 10 萬，投 10 年後就停止（共投入 100 萬），到 65 歲時
- **35 歲開始**，每年投入 10 萬，一路投到 65 歲（共投入 310 萬）

**結果是前者的終值反而較高**，儘管投入金額只有後者的三分之一。原因是前者那 100 萬多了 10 年的複利時間，而複利是指數成長——**越早的每一塊錢，被複利放大的次數越多**。

**這個例子最能說明「時間比金額重要」**，也是為什麼財務決策的第一課永遠是「越早開始越好」。

**折現的實際運用**：某供應商提出兩個付款方案——**方案 A 今天付 95 萬**，**方案 B 一年後付 100 萬**。若公司的資金成本為 8%：

1. 方案 B 的現值 \`= 100 / (1 + 0.08) ≈ 92.59\` 萬
2. 方案 A 的現值 \`= 95\` 萬（本來就是今天）
3. \`92.59 < 95\` → **選方案 B**

**若資金成本只有 3%**：方案 B 現值 \`= 100 / 1.03 ≈ 97.09\` 萬 > 95 萬 → **改選方案 A**。

**同樣的兩個方案，資金成本不同就有不同答案**——這正是折現率作為「機會成本」的意義：**你的錢在別處能賺多少，決定了你該不該提早付款。**`,
