          q: '如果我持有二十檔股票，是不是就沒有風險了？',
          framework: [
            '**先肯定一半**：二十檔如果夠分散，確實可以消除大部分的非系統性風險——個別公司的意外事件。',
            '**指出極限**：但系統性風險分散不掉。組合變異數隨檔數增加會趨近「平均共變異數」，不會趨近零。',
            '**講數學直覺**：因為個別變異數項的權重是 1/n 會消失，共變異數項的權重趨近 1 會留下來。',
            '**補實務警告**：而且如果這二十檔都在同一個產業或同一組因子上，相關係數很高，分散效果其實有限——分散要看因子暴露，不是看檔數。',
            '**最後給危機情境**：危機時各類資產的相關係數會一起上升趨近 1，最需要分散的時候分散反而失效。'
          ],
          pitfall: '直接答「是」是這題要抓的答案。另一個地雷是只講「還有系統性風險」卻說不出為什麼分散不掉——關鍵是共變異數項的權重不會消失。',
          schools: '**台大商研**可能追問這如何導出 CAPM（只有系統性風險該被補償）。**北大企研**較可能問實務配置，可講因子暴露與危機時相關係數上升。'
