          def: '將資產的必要報酬率表達為無風險利率加上 β 乘以市場風險溢酬的模型。其核心主張為僅系統性風險應獲得報酬補償，非系統性風險因可分散而不影響定價。',
          tip: '公式要能默寫。並記住一句話理解：必要報酬 = 時間的補償 + 風險的補償。'
