          explain: '折現率應反映該專案本身的風險，而非公司整體的平均風險。生技新藥的營運風險遠高於食品本業，其應有的必要報酬亦較高；若逕以公司既有的加權平均資金成本折現，等同於低估風險補償，將使專案的淨現值被系統性高估，可能導致公司接受實際上無法創造價值的投資。恰當作法是尋找業務相近的同業，取其權益 β 去槓桿後還原營運風險，再依本公司目標資本結構加槓桿，代入資本資產定價模型求得該專案適用的折現率。反之若以公司資金成本折現風險較低的專案，則會低估淨現值而錯失機會。'
