            '**給具體數字**：例如 ROE 只有 8%、股東要求 12%，那每保留一元就毀損價值——股東自己拿去投資還賺得比較多。',
            '**帶出管理意涵**：所以這種公司該把錢發還股東，而不是擴張。成熟產業的高配息與股票買回就是這個邏輯。',
