            '**給第二個理由——資產性質**：這個更關鍵。電信有基地台、機房這些有形資產，破產時還能變現，債權人有保障；生技的價值是研發能力跟人才，一旦傳出財務困難，人就走光了，債權人拿不到東西。',
            '**帶出間接成本**：而且財務危機的間接成本比直接成本大得多——顧客、供應商、員工在公司真的倒閉之前就會先跑，光是「預期」就足以造成傷害。',
            '**收在權衡理論**：所以最適負債比是在稅盾的好處跟財務危機成本之間取平衡，而這個平衡點主要由資產性質與現金流穩定度決定。'
