          pitfall: '只答「因為生技風險高」太籠統。真正的關鍵是**資產能不能在破產時變現**——這是有形資產與無形資產的差別，講出來層次差很多。',
          schools: '**台大商研**可能追問資產替換或債務積壓這兩個代理問題。**北大企研**較可能問實務判斷，可以補「所以生技業多半靠增資而不是舉債」。'
